<div class="admin-page-heading"><div><span class="admin-eyebrow">PORTFOLIO MANAGEMENT</span><p>Add and maintain real completed work shown on the public website.</p></div><a class="admin-button" href="<?= e(url('/admin/projects/create')) ?>">＋ Add Project</a></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>PROJECT</th><th>CATEGORY</th><th>LOCATION</th><th>VISIBILITY</th><th>ADDED</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($projects as $project): ?><tr><td><strong><?= e($project['title']) ?></strong><small><?= e($project['slug']) ?></small></td><td><?= e($project['category_name']??'Uncategorized') ?></td><td><?= e($project['location']?:'—') ?></td><td><span class="status <?= $project['is_published']?'status-completed':'status-closed' ?>"><?= $project['is_published']?'Published':'Draft' ?></span></td><td><?= e(format_date($project['created_at'])) ?></td><td class="actions-cell"><a class="table-action" href="<?= e(url('/admin/projects/'.$project['id'].'/edit')) ?>">Edit</a><form method="post" action="<?= e(url('/admin/projects/'.$project['id'].'/delete')) ?>" data-confirm="Delete this project? This cannot be undone."><?= csrf_field() ?><button class="table-danger" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$projects): ?><div class="admin-empty"><span>▧</span><h3>No projects added yet</h3><p>Add completed project photography to build your portfolio.</p></div><?php endif; ?></section>
